import math
import numpy as np
from scipy.stats import norm


def n_per_arm(delta, sigma, alpha=0.05, power=0.8, rho=0.0):
    z = norm.ppf(1 - alpha / 2) + norm.ppf(power)
    return math.ceil(2 * (1 - rho) * z ** 2 * sigma ** 2 / delta ** 2)


def randomise_within_blocks(block_ids, seed):
    rng = np.random.default_rng(seed)
    where = {}
    for i, b in enumerate(block_ids):
        where.setdefault(b, []).append(i)
    out = [None] * len(block_ids)
    for b, idx in where.items():
        if len(idx) != 2:
            raise ValueError('block ' + str(b) + ' needs exactly two orders')
        first = int(rng.integers(0, 2))
        out[idx[first]] = 'A'
        out[idx[1 - first]] = 'B'
    return out

